#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    string s;
    cin >> s;

    int ans = 1;

    for (int center = 0; center < N; center++) {
        int l = center, r = center;
        while (l >= 0 && r < N && s[l] == s[r]) {
            ans = max(ans, r - l + 1);
            l--;
            r++;
        }

        l = center;
        r = center + 1;
        while (l >= 0 && r < N && s[l] == s[r]) {
            ans = max(ans, r - l + 1);
            l--;
            r++;
        }
    }

    cout << ans << '\n';

    return 0;
}
